string formatEmployeeName = "Ada Lovelace";
decimal formatMeasuredHours = 8.256m;
decimal formatRecordedHours = 8.5m;
decimal formatScheduledHours = 8m;
decimal formatVarianceHours = formatRecordedHours - formatScheduledHours;

Console.WriteLine($"Measured: {formatEmployeeName} — {formatMeasuredHours:F2}");
Console.WriteLine($"Employee: {formatEmployeeName}\nMeasured hours: {formatMeasuredHours:F2}");

string formatRawHeading = """
TimeClock hours report
Values are displayed below.
""";
Console.WriteLine(formatRawHeading);

string formatReport = $"""
Employee: {formatEmployeeName}
Measured hours: {formatMeasuredHours:F2}
Recorded hours: {formatRecordedHours:F2}
Scheduled hours: {formatScheduledHours:F2}
Variance: {formatVarianceHours:+0.00;-0.00;0.00}
""";
Console.WriteLine(formatReport);
